/**
 * Fields whose values are shell commands, are used to build commands, or are pasted into the
 * prompts of agents that run commands. Every one is shown before approval.
 */
export const COMMAND_FIELDS = [
  'gates', 'scaffold', 'ci', 'e2e', 'e2eBackend', 'migrations', 'audit', 'packageManagers', 'contractSync', 'buildGateGuard',
  'sourceDirs', 'debugPatterns', 'gateTemplates', 'execWrapper',
];

/** How a manifest that does not parse is reported. Node's parse message quotes the text, so it is never shown. */
const NOT_JSON = 'not valid JSON (rule json)';

/** A manifest the workflows would reject or ignore; main() exits 2 for it. */
export class ManifestRejectedError extends Error {}

/**
 * Why the workflows would not use a manifest, checked with their own mergeOverlay as if it were the only
 * manifest and already approved: the first validation problem of a rejected file, or the reason an entry
 * is ignored (a first-party key, a stale first-party copy). Null when every entry would join the registry.
 * The reason is built from a JSON pointer and a rule with fixed texts, like the workflows' own reasons
 * (OD-17a V3): it never quotes a key name, a value or a parse message from the manifest.
 * @param {string} raw manifest file text
 * @param {string} source label the workflows report for it (decides whether it is a first-party location)
 * @returns {string|null} one line naming the problem and its fix
 * @example workflowRejection('{"name":"acme","bogus":1}', 'project:.claude/stacks/acme.json')
 * // '/order is missing (rule required). Fix: add it'
 */
export function workflowRejection(raw, source) {
  const registry = WORKFLOW_REGISTRY;
  let sha256 = null;
  try {
    sha256 = registry.manifestHash(JSON.parse(raw));
  } catch {
    // mergeOverlay reports the parse error
  }
  const store = JSON.stringify({ version: 1, trusted: sha256 ? [{ sha256 }] : [] });
  const merged = registry.mergeOverlay([{ source, raw }], store);
  if (merged.rejected.length) return merged.rejected[0].reason;
  if (merged.ignored.length) {
    const i = merged.ignored[0];
    if (i.reason === 'first-party key') return '/name is a first-party key, which the workflows ignore in this manifest (rule firstPartyKey). Fix: give the stack its own key';
    const stale = /^first-party key \(stale or edited copy; (.*)\)$/.exec(i.reason);
    if (stale) return `/ is a stale or edited copy of a first-party manifest, which the workflows ignore (rule staleCopy). Fix: ${stale[1]}`;
    return '/name is ignored by the workflows (rule ignored). Fix: check the manifest against stack.schema.json';
  }
  if (!merged.added.length) return '/ declares no stack the workflows would add. Fix: check the manifest against stack.schema.json';
  return null;
}

/**
 * The short form of a rejection reason for listings: its pointer and rule only.
 * @param {string} reason a workflowRejection reason
 * @returns {string} for example '/role (rule required)'
 */
export function briefReason(reason) {
  const m = /^(\S+) .*?\(rule ([A-Za-z]+)\)/.exec(reason);
  return m ? `${m[1]} (rule ${m[2]})` : reason.split(' ')[0];
}

/**
 * Serializes a JSON value with object keys sorted in code-unit order and no whitespace.
 * @param {unknown} value parsed JSON
 * @returns {string} canonical text
 */
export function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

/**
 * Canonical text of a parsed manifest: `$schema` is dropped from the top-level object, or from each top-level element of an array.
 * @param {unknown} parsed parsed manifest
 * @returns {string} canonical text
 */
export function canonicalManifest(parsed) {
  const strip = (e) => {
    if (e === null || typeof e !== 'object' || Array.isArray(e) || !Object.hasOwn(e, '$schema')) return e;
    const { $schema, ...rest } = e;
    return rest;
  };
  return canonicalJson(Array.isArray(parsed) ? parsed.map(strip) : strip(parsed));
}

/**
 * @param {unknown} parsed parsed manifest
 * @returns {string} 64-character hex sha256 of the canonical manifest
 */
export function manifestHash(parsed) {
  return crypto.createHash('sha256').update(canonicalManifest(parsed), 'utf8').digest('hex');
}

/**
 * The Claude Code config directory, which holds the user stacks, the plugin list and the user settings.
 * The trust store does not live here (storePath).
 * @param {NodeJS.ProcessEnv} [env] environment
 * @returns {string} the Claude Code config directory
 */
export function configDir(env = process.env) {
  return env.CLAUDE_CONFIG_DIR || path.join(env.HOME || os.homedir(), '.claude');
}

// A path with symlinks resolved as far as it exists, so a directory that is not created yet still compares.
function resolvedPath(p) {
  const rest = [];
  let cur = path.resolve(p);
  for (;;) {
    try {
      return path.join(fs.realpathSync(cur), ...rest);
    } catch {
      const parent = path.dirname(cur);
      if (parent === cur) return path.resolve(p);
      rest.unshift(path.basename(cur));
      cur = parent;
    }
  }
}

// The git toplevel of a directory, or null outside a repository or without git. rev-parse runs no hook.
function gitToplevel(cwd) {
  const r = spawnSync('git', ['rev-parse', '--show-toplevel'], { cwd, encoding: 'utf8', timeout: 5000, stdio: ['ignore', 'pipe', 'ignore'] });
  const top = r.status === 0 ? r.stdout.trim() : '';
  return top ? top : null;
}

// Every ancestor of a directory (itself included) that holds a .git file or directory.
function gitAncestors(cwd) {
  const out = [];
  for (let dir = resolvedPath(cwd); ; dir = path.dirname(dir)) {
    if (fs.existsSync(path.join(dir, '.git'))) out.push(dir);
    if (path.dirname(dir) === dir) return out;
  }
}

/**
 * Why the config directory must not be used: it is inside a directory a cloned repository or workspace
 * controls, where the repository (or a project settings `env` that sets CLAUDE_CONFIG_DIR) could plant
 * user stacks, a plugin list and user settings. Those directories are the current directory,
 * CLAUDE_PROJECT_DIR, the git toplevel of the current directory and every ancestor of the current
 * directory that holds .git. The user stacks, plugin list and settings are then not read or written.
 * The trust store is not affected: it lives in the OS home directory (storePath), whatever the config
 * directory is. Planted user stacks would still need an approval, so this check is defense in depth.
 * @param {NodeJS.ProcessEnv} [env] environment (CLAUDE_PROJECT_DIR, when set, is a project directory too)
 * @param {string} [cwd] project directory
 * @returns {string|null} the problem, or null when the config directory is outside all of them
 * @example configDirProblem({ CLAUDE_CONFIG_DIR: '/work/app/.cfg' }, '/work/app')
 * // 'config directory inside the project (/work/app/.cfg is in /work/app)'
 */
export function configDirProblem(env = process.env, cwd = process.cwd()) {
  const dir = resolvedPath(configDir(env));
  const roots = [cwd, env.CLAUDE_PROJECT_DIR, gitToplevel(cwd), ...gitAncestors(cwd)];
  for (const root of roots.filter(Boolean).map(resolvedPath)) {
    if (dir === root || dir.startsWith(root.endsWith(path.sep) ? root : root + path.sep)) {
      return `config directory inside the project (${dir} is in ${root})`;
    }
  }
  return null;
}

// Throws when the config directory may not be written (configDirProblem).
function assertConfigDirUsable(env, cwd) {
  const problem = configDirProblem(env, cwd);
  if (problem) throw new Error(`${problem}; nothing was written. Fix: point CLAUDE_CONFIG_DIR (or HOME) outside the project, then run /stack-trust again.`);
}

/**
 * The current user's home directory as the OS user database records it (getpwuid). Unlike os.homedir(),
 * os.userInfo() ignores $HOME, so neither $HOME nor CLAUDE_CONFIG_DIR, which a project's settings `env`
 * can set, moves the trust store into a directory a repository controls.
 * @returns {string} absolute home directory
 * @throws {Error} when the user database has no absolute home directory for the current user
 */
export function osHomeDir() {
  let home = '';
  try {
    home = os.userInfo().homedir;
  } catch {
    // no entry for this uid, for example in a container started with an arbitrary user id
  }
  if (typeof home !== 'string' || !path.isAbsolute(home)) {
    throw new Error('no home directory for the current user in the OS user database. Fix: run Claude Code as a user that has a home directory');
  }
  return home;
}

/**
 * The trust store: <home>/.claude/sdd-kit/trusted-stacks.json with <home> from osHomeDir. Fixed on
 * purpose; $HOME and CLAUDE_CONFIG_DIR do not move it.
 * @returns {string} absolute path of the trust store
 * @throws {Error} when the OS user database has no home directory for the current user
 */
export function storePath() {
  return path.join(osHomeDir(), '.claude', 'sdd-kit', 'trusted-stacks.json');
}

/**
 * Reads the approved hashes from storePath. An absent store approves nothing; so does one that does not parse.
 * @returns {{ hashes: Set<string>, entries: object[], error: string|null }} approvals and a read problem, if any
 */
export function readStore() {
  let file;
  let text;
  try {
    file = storePath();
  } catch (e) {
    return { hashes: new Set(), entries: [], error: `trust store unreadable (${e.message.split('. Fix:')[0]})` };
  }
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch (e) {
    if (e.code === 'ENOENT') return { hashes: new Set(), entries: [], error: null };
    return { hashes: new Set(), entries: [], error: `trust store unreadable (${e.message})` };
  }
  try {
    const data = JSON.parse(text);
    const trusted = Array.isArray(data && data.trusted) ? data.trusted : null;
    if (!trusted) throw new Error('missing "trusted" array');
    const entries = trusted.filter((t) => t && typeof t.sha256 === 'string');
    return { hashes: new Set(entries.map((t) => t.sha256)), entries, error: null };
  } catch (e) {
    return { hashes: new Set(), entries: [], error: `trust store unreadable (${e.message})` };
  }
}

/**
 * The Read allow rules that let a workflow's Detect agent read the trust store (storePath, in the OS home
 * directory), the user stacks directory, the installed plugin list and the plugin cache (where every
 * installed plugin's `<installPath>/stack.json` lives) without a prompt, and nothing else.
 * A path under `$HOME/.claude` uses the `~/` form; any other path (a relocated CLAUDE_CONFIG_DIR, or a
 * $HOME that is not the OS home directory) needs the absolute `//` form, because a `~/.claude/...` rule
 * does not cover it.
 * @param {NodeJS.ProcessEnv} [env] environment
 * @returns {string[]} four permission rules, for example `Read(~/.claude/stacks/**)`
 * @throws {Error} when the OS user database has no home directory for the current user
 */
export function detectReadRules(env = process.env) {
  const tilde = path.resolve(env.HOME || os.homedir(), '.claude');
  const ruleBase = (dir) => (path.resolve(dir) === tilde ? '~/.claude' : `//${path.resolve(dir).replace(/^\/+/, '')}`);
  const base = ruleBase(configDir(env));
  return [
    `Read(${ruleBase(path.join(osHomeDir(), '.claude'))}/sdd-kit/trusted-stacks.json)`,
    `Read(${base}/stacks/**)`,
    `Read(${base}/plugins/installed_plugins.json)`,
    `Read(${base}/plugins/cache/**)`,
  ];
}

/**
 * @param {NodeJS.ProcessEnv} [env] environment
 * @returns {string} the user settings file, which lives in the config directory
 */
export function userSettingsPath(env = process.env) {
  return path.join(configDir(env), 'settings.json');
}

function readSettings(file) {
  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch (e) {
    if (e.code === 'ENOENT') return {};
    throw new Error(`Cannot read ${file} (${e.message}). Fix: check its permissions, then run /stack-trust again.`);
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    throw new Error(`${file} is not valid JSON (${e.message}); nothing was changed. Fix: repair the file, then run /stack-trust again.`);
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error(`${file} is not a JSON object; nothing was changed. Fix: repair the file, then run /stack-trust again.`);
  return data;
}

/**
 * Which of the Detect Read rules the user settings already allow.
 * @param {NodeJS.ProcessEnv} [env] environment
 * @returns {{ settings: string, rules: { rule: string, present: boolean }[] }} settings file and per-rule status
 */
export function readRuleStatus(env = process.env, cwd = process.cwd()) {
  assertConfigDirUsable(env, cwd);
  const settings = userSettingsPath(env);
  const data = readSettings(settings);
  const allow = data.permissions && Array.isArray(data.permissions.allow) ? data.permissions.allow : [];
  return { settings, rules: detectReadRules(env).map((rule) => ({ rule, present: allow.includes(rule) })) };
}

/**
 * Appends the missing Detect Read rules to `permissions.allow` of the user settings, keeping every
 * other key and rule as it was. Running it again changes nothing. An unparseable file is left alone.
 * @param {NodeJS.ProcessEnv} [env] environment
 * @returns {{ settings: string, added: string[] }} settings file and the rules written
 */
export function addReadRules(env = process.env, cwd = process.cwd()) {
  assertConfigDirUsable(env, cwd);
  const settings = userSettingsPath(env);
  const data = readSettings(settings);
  if (data.permissions !== undefined && (typeof data.permissions !== 'object' || data.permissions === null || Array.isArray(data.permissions))) {
    throw new Error(`${settings} has a "permissions" value that is not an object; nothing was changed. Fix: repair the file, then run /stack-trust again.`);
  }
  const permissions = data.permissions || {};
  if (permissions.allow !== undefined && !Array.isArray(permissions.allow)) {
    throw new Error(`${settings} has a "permissions.allow" value that is not a list; nothing was changed. Fix: repair the file, then run /stack-trust again.`);
  }
  const allow = permissions.allow || [];
  const added = detectReadRules(env).filter((rule) => !allow.includes(rule));
  if (!added.length) return { settings, added };
  permissions.allow = [...allow, ...added];
  data.permissions = permissions;
  fs.mkdirSync(path.dirname(settings), { recursive: true });
  fs.writeFileSync(settings, `${JSON.stringify(data, null, 2)}\n`);
  return { settings, added };
}

function manifestEntries(parsed) {
  return (Array.isArray(parsed) ? parsed : [parsed]).filter((e) => e && typeof e === 'object');
}

// A staged copy of a first-party manifest is informational: it equals the inlined entry, so it is already trusted.
function isFirstPartyCopy(parsed, registry) {
  const list = manifestEntries(parsed);
  if (!list.length) return false;
  return list.every((e) => {
    const inlined = registry.entries && registry.entries[e.name];
    return inlined && canonicalJson(inlined) === canonicalManifest(e);
  });
}

function readJsonFile(file) {
  try {
    return { text: fs.readFileSync(file, 'utf8') };
  } catch {
    return null;
  }
}

function listJson(dir) {
  try {
    return fs.readdirSync(dir).filter((f) => f.endsWith('.json')).sort().map((f) => path.join(dir, f));
  } catch {
    return [];
  }
}

function installedPluginDirs(env) {
  const out = [];
  const file = readJsonFile(path.join(configDir(env), 'plugins', 'installed_plugins.json'));
  if (!file) return out;
  try {
    const plugins = JSON.parse(file.text).plugins || {};
    for (const [id, installs] of Object.entries(plugins)) {
      for (const inst of Array.isArray(installs) ? installs : []) {
        if (inst && typeof inst.installPath === 'string') out.push({ id, name: id.split('@')[0], dir: inst.installPath });
      }
    }
  } catch {
    // an unreadable plugin list only means no plugin manifests are discovered
  }
  return out;
}

const MAX_ANCESTORS = 64;

/**
 * Command lines of this process's ancestors, nearest first, read with `ps -o ppid=,args=`.
 * `claude plugin list --json` does not list --plugin-dir plugins, so their paths are read from the
 * command line of the Claude Code process (or whichever ancestor carries the flags).
 * @param {{ pid?: number, ps?: (pid: number) => string|null }} [opts] start pid (the parent of this process) and a ps reader
 * @returns {string[]} one command line per ancestor; empty when ps is unavailable
 */
export function ancestorCommandLines({ pid = process.ppid, ps = readPs } = {}) {
  const lines = [];
  const seen = new Set();
  let current = pid;
  while (Number.isInteger(current) && current > 1 && !seen.has(current) && lines.length < MAX_ANCESTORS) {
    seen.add(current);
    const row = ps(current);
    const m = row && /^\s*(\d+)\s+(.*)$/s.exec(row.trim());
    if (!m) break;
    lines.push(m[2].trim());
    current = Number(m[1]);
  }
  return lines;
}

function readPs(pid) {
  const r = spawnSync('ps', ['-o', 'ppid=,args=', '-p', String(pid)], { encoding: 'utf8' });
  return r.status === 0 ? r.stdout : null;
}

/**
 * The --plugin-dir values on one command line, in both `--plugin-dir <path>` and `--plugin-dir=<path>`
 * forms. ps prints arguments joined by spaces, so a path that contains a space cannot be recovered;
 * such an add-on is found through a .claude/stack-addons/ entry (a directory or a symlink) instead.
 * @param {string} commandLine one line of ps output
 * @returns {string[]} the paths as written
 */
export function pluginDirArgs(commandLine) {
  const tokens = String(commandLine).split(/\s+/).filter(Boolean);
  const dirs = [];
  for (let i = 0; i < tokens.length; i++) {
    if (tokens[i] === '--plugin-dir' && i + 1 < tokens.length) dirs.push(tokens[++i]);
    else if (tokens[i].startsWith('--plugin-dir=') && tokens[i].length > '--plugin-dir='.length) dirs.push(tokens[i].slice('--plugin-dir='.length));
  }
  return dirs;
}

// The Claude Code executable: a `claude` binary, a path through a `claude` directory (native installs keep
// versions under .../claude/versions/<n>), or node running the published @anthropic-ai/claude-code CLI.
const CLAUDE_PROGRAM = /(^|\/)claude(-code)?(\/|$)|@anthropic-ai\/claude-code\//;

/**
 * Whether a command line is a Claude Code process. Only those are read for --plugin-dir, so a shell
 * whose `-c` script merely mentions the flag is never taken for the session.
 * @param {string} commandLine one line of ps output
 * @returns {boolean}
 */
export function isClaudeCommand(commandLine) {
  const [program = '', script = ''] = String(commandLine).trim().split(/\s+/);
  if (CLAUDE_PROGRAM.test(program)) return true;
  return /(^|\/)node$/.test(program) && CLAUDE_PROGRAM.test(script);
}

/**
 * Plugins this Claude Code session loaded with --plugin-dir: the flags on every ancestor that is a
 * Claude Code process. A relative path resolves against the project directory, which is where
 * `claude` normally starts.
 * @param {{ cwd?: string, listing?: string[] }} [opts] directory relative paths resolve against, and the
 *   ancestor command lines (defaults to ancestorCommandLines())
 * @returns {{ name: string, path: string }[]} plugin.json name (directory name when absent) and absolute path, deduplicated
 */
export function sessionPluginDirs({ cwd = process.cwd(), listing } = {}) {
  const lines = listing === undefined ? ancestorCommandLines() : listing;
  const out = [];
  const seen = new Set();
  for (const line of lines.filter(isClaudeCommand)) {
    for (const dir of pluginDirArgs(line)) {
      const abs = path.resolve(cwd, dir.replace(/^~(?=\/|$)/, os.homedir()));
      if (seen.has(abs)) continue;
      seen.add(abs);
      out.push({ name: pluginName(abs, path.basename(abs)), path: abs });
    }
  }
  return out;
}

function realOrSelf(p) {
  try {
    return fs.realpathSync(p);
  } catch {
    return p;
  }
}

/**
 * Every add-on reported as `plugin:<name>@inline`: directories (or symlinks) under the project's
 * .claude/stack-addons/, then the session's --plugin-dir paths. The same directory is listed once.
 * @param {{ cwd?: string, listing?: string[] }} [opts] project directory and ancestor command lines (see sessionPluginDirs)
 * @returns {{ name: string, path: string, origin: 'stack-addons'|'plugin-dir', alias: string|null }[]} inline add-ons
 */
export function inlineAddons({ cwd = process.cwd(), listing } = {}) {
  const out = [];
  const seen = new Set();
  const push = (entry) => {
    const key = realOrSelf(entry.path);
    if (seen.has(key)) return;
    seen.add(key);
    out.push(entry);
  };
  const base = path.join(cwd, '.claude', 'stack-addons');
  let names = [];
  try {
    names = fs.readdirSync(base).sort();
  } catch {
    // no add-on directory
  }
  for (const d of names) {
    const dir = path.join(base, d);
    if (!fs.statSync(dir, { throwIfNoEntry: false })?.isDirectory()) continue;
    push({ name: pluginName(dir, d), path: dir, origin: 'stack-addons', alias: `project:.claude/stack-addons/${d}/stack.json` });
  }
  for (const p of sessionPluginDirs({ cwd, listing })) push({ ...p, origin: 'plugin-dir', alias: null });
  return out;
}

/**
 * Finds every overlay manifest visible from a project: project .claude/stacks, inline add-ons
 * (.claude/stack-addons and the session's --plugin-dir paths), the user stacks directory and
 * installed plugins that ship a stack.json.
 * First-party plugins, inline add-ons under a first-party name that add no keys of their own, and
 * staged copies of first-party manifests are left out.
 * @param {{ cwd?: string, env?: NodeJS.ProcessEnv, listing?: string[] }} [opts] project directory, environment and
 *   ancestor command lines (defaults to the real process tree)
 * @returns {{ source: string, aliases: string[], file: string, pluginDir: string|null, sha256: string|null, keys: string[], parsed: unknown, error: string|null }[]} overlays
 */
export function discoverOverlays({ cwd = process.cwd(), env = process.env, listing } = {}) {
  const registry = FIRST_PARTY_REGISTRY;
  const firstPartyPlugins = new Set(registry.firstPartyPlugins || []);
  const found = [];
  const add = (source, file, aliases = [], pluginDir = null) => {
    const read = readJsonFile(file);
    if (!read) return;
    let parsed;
    try {
      parsed = JSON.parse(read.text);
    } catch {
      // Node's parse message quotes the manifest text, so only the rule is reported.
      found.push({ source, aliases, file, pluginDir, sha256: null, keys: [], parsed: null, raw: read.text, error: NOT_JSON });
      return;
    }
    if (isFirstPartyCopy(parsed, registry)) return;
    found.push({ source, aliases, file, pluginDir, sha256: manifestHash(parsed), keys: manifestEntries(parsed).map((e) => e.name), parsed, raw: read.text, error: null });
  };
  for (const f of listJson(path.join(cwd, '.claude', 'stacks'))) add(`project:.claude/stacks/${path.basename(f)}`, f);
  for (const a of inlineAddons({ cwd, listing })) {
    const file = path.join(a.path, 'stack.json');
    if (firstPartyPlugins.has(a.name)) {
      // The workflows compare a first-party-named add-on that carries only first-party keys with the
      // inlined registry (present or stale, never trusted), so it is no overlay. One that adds its own
      // keys is an overlay like any other; it keeps only the full label, because the short
      // plugin:<name> form names the first-party plugin.
      if (carriesOwnKeys(file, registry)) add(`plugin:${a.name}@inline`, file, [], a.path);
      continue;
    }
    add(`plugin:${a.name}@inline`, file, [`plugin:${a.name}`, ...(a.alias ? [a.alias] : [])], a.path);
  }
  // A config directory inside the project holds no user stacks or plugin list this script will read.
  // The trust store is never there (storePath), so this only keeps planted manifests out of the list.
  const configUsable = !configDirProblem(env, cwd);
  for (const f of configUsable ? listJson(path.join(configDir(env), 'stacks')) : []) {
    add(`user:~/.claude/stacks/${path.basename(f)}`, f, [`user:stacks/${path.basename(f)}`]);
  }
  for (const p of configUsable ? installedPluginDirs(env) : []) {
    if (firstPartyPlugins.has(p.name)) continue;
    add(`plugin:${p.id}`, path.join(p.dir, 'stack.json'), [`plugin:${p.name}`], p.dir);
  }
  return found;
}

// Whether a manifest file declares at least one key the core registry does not inline.
function carriesOwnKeys(file, registry) {
  const read = readJsonFile(file);
  if (!read) return false;
  try {
    return manifestEntries(JSON.parse(read.text)).some((e) => !(registry.entries && Object.hasOwn(registry.entries, e.name)));
  } catch {
    return true;
  }
}

// The plugin name a --plugin-dir session reports for a project add-on directory.
function pluginName(dir, fallback) {
  const read = readJsonFile(path.join(dir, '.claude-plugin', 'plugin.json'));
  try {
    const name = read && JSON.parse(read.text).name;
    if (typeof name === 'string' && name) return name;
  } catch {
    // an unreadable plugin.json falls back to the directory name
  }
  return fallback;
}

/**
 * Finds a discovered overlay by its source label or one of its accepted aliases.
 * @param {string} source label from --list or from a workflow report
 * @param {object} [opts] see discoverOverlays
 * @returns {object|undefined} the overlay
 */
export function findOverlay(source, opts = {}) {
  return discoverOverlays(opts).find((o) => o.source === source || o.aliases.includes(source));
}

/**
 * @param {object} opts see discoverOverlays
 * @returns {{ overlays: (object & { trusted: boolean, rejected: string|null })[], storeError: string|null }} overlays with
 *   their trust status; rejected is why the workflows reject or ignore the manifest (null when they use it), a
 *   rejected manifest is never trusted, and its keys are not reported
 */
export function listOverlays(opts = {}) {
  const store = readStore();
  const overlays = discoverOverlays(opts).map((o) => {
    const rejected = workflowRejection(o.raw, o.source);
    // A rejected manifest's keys are text the manifest chose, so listings do not report them.
    return { ...o, keys: rejected ? [] : o.keys, rejected, trusted: !rejected && o.sha256 !== null && store.hashes.has(o.sha256) };
  });
  return { overlays, storeError: store.error };
}

/**
 * Command-bearing fields of a manifest, as shown to the user before approval.
 * @param {unknown} parsed parsed manifest
 * @returns {object[]} one summary per entry
 */
export function commandFields(parsed) {
  return manifestEntries(parsed).map((e) => {
    const summary = { name: e.name, agent: e.agent };
    for (const f of COMMAND_FIELDS) if (e[f] !== undefined) summary[f] = e[f];
    return summary;
  });
}

/**
 * Hook commands of the plugin directory a manifest ships in. Claude Code runs them whenever the
 * plugin is loaded, so they are shown for review, but the manifest approval does not cover them.
 * @param {string|null} dir plugin directory, null for a bare manifest file
 * @returns {{ event: string, matcher: string|null, command: string }[]} hook commands
 */
export function pluginHookCommands(dir) {
  if (!dir) return [];
  const read = readJsonFile(path.join(dir, 'hooks', 'hooks.json'));
  if (!read) return [];
  const out = [];
  try {
    for (const [event, groups] of Object.entries(JSON.parse(read.text).hooks || {})) {
      for (const g of Array.isArray(groups) ? groups : []) {
        for (const h of Array.isArray(g && g.hooks) ? g.hooks : []) {
          const command = h && (h.command || h.prompt || h.url);
          if (typeof command === 'string') out.push({ event, matcher: g.matcher || null, command });
        }
      }
    }
  } catch {
    out.push({ event: 'unknown', matcher: null, command: 'hooks/hooks.json is not valid JSON; inspect it by hand' });
  }
  return out;
}

/**
 * Whether a manifest file's current content is approved. Staged copies of first-party manifests are trusted.
 * A manifest the workflows would reject or ignore is never trusted, whatever the store holds (rejected: true).
 * @param {string} file manifest path
 * @returns {{ trusted: boolean, rejected?: boolean, sha256: string|null, reason: string }} verdict and a one-line reason
 */
export function checkManifest(file) {
  let parsed;
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (e) {
    return { trusted: false, sha256: null, reason: `${file} cannot be read (${e.code || 'read error'}). Fix: check the path, then run /stack-trust.` };
  }
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { trusted: false, rejected: true, sha256: null, reason: `${file} is ${NOT_JSON}. Fix: correct the manifest, then run /stack-trust.` };
  }
  const sha256 = manifestHash(parsed);
  if (isFirstPartyCopy(parsed, FIRST_PARTY_REGISTRY)) return { trusted: true, sha256, reason: `first-party manifest ${file}` };
  // The workflows accept only their own source labels; a checked file is judged as a project manifest of its
  // name, or of a neutral name when its name holds characters a source label may not.
  const base = path.basename(file);
  const rejection = workflowRejection(raw, `project:.claude/stacks/${/^[A-Za-z0-9._~@:-]{1,90}\.json$/.test(base) ? base : 'manifest.json'}`);
  if (rejection) return { trusted: false, rejected: true, sha256, reason: `rejected ${file}: ${rejection}. The workflows do not use this manifest, so its commands never run.` };
  const store = readStore();
  if (store.hashes.has(sha256)) return { trusted: true, sha256, reason: `trusted ${file} sha256 ${sha256}` };
  const why = store.error ? `${store.error}, so nothing is trusted` : 'its sha256 is not in the trust store';
  return { trusted: false, sha256, reason: `untrusted ${file} sha256 ${sha256}: ${why}. Fix: run /stack-trust.` };
}

/**
 * The error for a source that matches no overlay. A short plugin:<name> form that names a first-party
 * plugin is called out, since an add-on loaded with --plugin-dir under that name answers only to its
 * full plugin:<name>@inline label.
 * @param {string} source the label the user passed
 * @returns {string} message with its Fix
 */
function notFoundMessage(source) {
  const m = /^plugin:([a-z0-9-]+)$/.exec(source);
  if (m && FIRST_PARTY_REGISTRY.firstPartyPlugins.includes(m[1])) {
    return `${source} is the name of a first-party plugin, which needs no approval. Fix: approve it by its full source label ${source}@inline if it is an add-on loaded with --plugin-dir under that name, or run trust-store.mjs --list to see the sources.`;
  }
  return `No overlay manifest '${source}'. Fix: run trust-store.mjs --list to see the sources.`;
}

/**
 * Records the current hash of an overlay manifest. Replaces an older approval of the same source.
 * Throws ManifestRejectedError, and records nothing, for a manifest the workflows would reject or ignore.
 * @param {string} source overlay source as listed by --list
 * @param {{ cwd?: string, env?: NodeJS.ProcessEnv, now?: Date }} [opts] project directory, environment, clock
 * @returns {{ sha256: string, keys: string[], source: string }} the recorded approval
 */
export function approve(source, opts = {}) {
  const overlay = findOverlay(source, opts);
  if (!overlay) throw new Error(notFoundMessage(source));
  if (overlay.error) throw new Error(`${source} is ${overlay.error}. Fix: correct the manifest first.`);
  const rejection = workflowRejection(overlay.raw, overlay.source);
  if (rejection) throw new ManifestRejectedError(`Not approved: the workflows reject ${overlay.source}: ${rejection}.`);
  let file;
  try {
    file = storePath();
  } catch (e) {
    throw new Error(`Cannot locate the trust store: ${e.message.replace('. Fix:', '; nothing was written. Fix:')}.`);
  }
  const store = readStore();
  const labels = new Set([overlay.source, ...overlay.aliases]);
  const kept = store.error ? [] : store.entries.filter((t) => !labels.has(t.source));
  const record = { sha256: overlay.sha256, keys: overlay.keys, source: overlay.source, approvedAt: (opts.now || new Date()).toISOString() };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${JSON.stringify({ version: 1, trusted: [...kept, record] }, null, 2)}\n`);
  return record;
}

function main(argv) {
  const json = argv.includes('--json');
  const args = argv.filter((a) => a !== '--json');
  const [cmd, arg, extra] = args;
  const out = (s) => process.stdout.write(`${s}\n`);
  try {
    if (cmd === '--list-untrusted' || cmd === '--list') {
      const { overlays, storeError } = listOverlays();
      const rows = cmd === '--list' ? overlays : overlays.filter((o) => !o.trusted);
      if (storeError) process.stderr.write(`${storeError}; every overlay is treated as untrusted\n`);
      const configProblem = configDirProblem();
      if (configProblem) process.stderr.write(`${configProblem}; user stacks and plugins there are not listed\n`);
      if (json) {
        out(JSON.stringify(rows.map(({ source, aliases, sha256, keys, trusted, rejected, error }) => ({ source, aliases, sha256, keys, trusted, rejected, error })), null, 2));
      } else {
        const row = (o) => (o.rejected ? `rejected\t${o.source}\t${briefReason(o.rejected)}` : `${o.trusted ? 'trusted' : 'untrusted'}\t${o.source}\t${o.keys.join(',')}`);
        for (const o of rows) out(cmd === '--list' ? row(o) : o.source);
      }
      return 0;
    }
    if (cmd === '--show' && arg) {
      const o = findOverlay(arg);
      if (!o) throw new Error(notFoundMessage(arg));
      if (o.error) throw new Error(`${arg} is ${o.error}.`);
      const shown = { source: o.source, file: o.file, sha256: o.sha256, entries: commandFields(o.parsed) };
      const rejection = workflowRejection(o.raw, o.source);
      if (rejection) {
        shown.rejected = `the workflows reject this manifest and --approve refuses it: ${rejection}`;
        shown.problems = WORKFLOW_REGISTRY.validateStackManifest(o.parsed, { overlay: true }).map((p) => `${p.pointer} ${p.problem}. Fix: ${p.fix}`);
      }
      const hooks = pluginHookCommands(o.pluginDir);
      if (hooks.length) shown.pluginHooks = { note: 'run by Claude Code whenever this plugin is loaded; not covered by this approval', commands: hooks };
      out(JSON.stringify(shown, null, 2));
      return 0;
    }
    if (cmd === '--approve' && arg) {
      const r = approve(arg);
      out(`Approved ${r.source} (${r.keys.join(', ')}) sha256 ${r.sha256}`);
      return 0;
    }
    if ((cmd === 'check' || cmd === '--check') && arg && extra === undefined) {
      const r = checkManifest(arg);
      (r.trusted ? process.stdout : process.stderr).write(`${r.reason}\n`);
      if (r.rejected) return 2;
      return r.trusted ? 0 : 1;
    }
    if (cmd === '--plugin-dirs' && arg === undefined) {
      const rows = inlineAddons().map((a) => ({ ...a, source: `plugin:${a.name}@inline`, stackJson: fs.existsSync(path.join(a.path, 'stack.json')) }));
      if (json) out(JSON.stringify(rows, null, 2));
      else for (const r of rows) out(`${r.source}\t${r.path}\t${r.origin}${r.stackJson ? '\tstack.json' : ''}`);
      return 0;
    }
    if (cmd === '--read-rules' && arg === undefined) {
      const { settings, rules } = readRuleStatus();
      if (json) out(JSON.stringify(rules.map((r) => ({ ...r, settings })), null, 2));
      else for (const r of rules) out(`${r.present ? 'present' : 'missing'}\t${r.rule}`);
      return 0;
    }
    if (cmd === '--add-read-rules' && arg === undefined) {
      const { settings, added } = addReadRules();
      out(added.length ? `Added to ${settings}: ${added.join(', ')}` : `All Detect Read rules already present in ${settings}`);
      return 0;
    }
    if (cmd === '--hash' && arg) {
      out(manifestHash(JSON.parse(fs.readFileSync(arg, 'utf8'))));
      return 0;
    }
  } catch (e) {
    process.stderr.write(`${e.message}\n`);
    return e instanceof ManifestRejectedError ? 2 : 1;
  }
  process.stderr.write('Usage: trust-store.mjs --list-untrusted [--json] | --list [--json] | --show <source> | --approve <source> | --hash <file> | --plugin-dirs [--json] | --read-rules [--json] | --add-read-rules | check <file>\n');
  return 2;
}

if (process.argv[1] && fs.realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv.slice(2)));
